};

function extractWikipediaTitle(tags) {
  if (typeof tags.wikipedia !== 'string') return null;
  const parts = tags.wikipedia.split(':');
  if (parts.length >= 2 && parts[0] === 'en') return parts.slice(1).join(':').replace(/ /g, '_');
  return null;
}

async function titleFromWikidata(qid) {
  if (!qid) return null;
  const data = await fetchJSON(`https://www.wikidata.org/wiki/Special:EntityData/${qid}.json`);
  const entity = data?.entities?.[qid];
  const sitelink = entity?.sitelinks?.enwiki;
  return sitelink?.title?.replace(/ /g, '_') || null;
}

async function fetchWikipediaSummary(title) {
  const url = `https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(title)}`;
  const data = await fetchJSON(url);
  if (!data || data.type === 'disambiguation' || data.title === 'Not found.') return null;
  return data;
}

async function searchWikipedia(query, collegeName) {
  // Search only with college context — building names alone are too ambiguous.
  const url = `https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(`${query} ${collegeName}`)}&srlimit=3&format=json&origin=*`;
  const data = await fetchJSON(url);
  const hits = data?.query?.search || [];
  if (!hits.length) return null;

  // Verify each candidate by fetching its summary.
  for (const hit of hits) {
    const title = hit.title.replace(/ /g, '_');
    const summary = await fetchWikipediaSummary(title);
    if (!summary) continue;
    if (isRelevantMatch(summary, query, collegeName)) {
      return { title, summary };
    }
  }
  return null;
}

async function fetchWikidataFacts(qid) {
  if (!qid) return {};
  const data = await fetchJSON(`https://www.wikidata.org/wiki/Special:EntityData/${qid}.json`);
  const entity = data?.entities?.[qid];
  const claims = entity?.claims || {};
  const facts = {};
  const inception = claims.P571?.[0]?.mainsnak?.datavalue?.value?.time;
  if (inception) facts.built = inception.split('-')[0].replace(/^\+/, '');
  const height = claims.P2048?.[0]?.mainsnak?.datavalue?.value;
  if (height?.amount) facts.height = `${Math.round(Number(height.amount))} m`;
  return facts;
}

async function enrichBuilding(feature, collegeName) {
  const t = feature.properties || {};
  if (!t.name) return null;

  // Prefer explicit OSM tags (trust them)
  let title = extractWikipediaTitle(t);
  let summary = null;
  if (!title && t.wikidata) title = await titleFromWikidata(t.wikidata);
  if (title) summary = await fetchWikipediaSummary(title);

  // Otherwise search with stricter relevance (article must mention the college)
  if (!summary) {
    const hit = await searchWikipedia(t.name, collegeName);
    if (hit) { title = hit.title; summary = hit.summary; }
  }

  if (!summary) return { _wikiTried: true };

  const qid = summary.wikibase_item || t.wikidata;
  const facts = await fetchWikidataFacts(qid);

  return {
    _wikiTried: true,
    wikiTitle: title,
    wikiDescription: summary.description || null,
    wikiExtract: summary.extract || null,
    wikiUrl: summary.content_urls?.desktop?.page || null,
    wikiPhoto: summary.originalimage?.source || summary.thumbnail?.source || null,
    wikiBuilt: facts.built || null,
    wikiHeight: facts.height || null,
  };
}

async function enrichCampus(slug, force) {
  const file = path.join(BATCH_DIR, `${slug}.geojson`);
  let data;
  try {
    data = JSON.parse(readFileSync(file, 'utf8'));
  } catch (cause) {
    throw new Error(`Couldn't read ${file}`, { cause });
  }

  const collegeName = COLLEGE_NAME[slug] || slug;
  const toEnrich = data.features.filter((f) => {
    const p = f.properties || {};
    if (!p.name) return false;
    if (!force && p._wikiTried) return false;
    return true;
  });

  if (!toEnrich.length) {
    console.log(`  ✓ ${slug}: nothing to enrich`);
    return;
  }

  console.log(`  → ${slug}: enriching ${toEnrich.length}/${data.features.length} named buildings...`);

  const WIKI_FIELDS = ['wikiTitle','wikiDescription','wikiExtract','wikiUrl','wikiPhoto','wikiBuilt','wikiHeight'];
  let succeeded = 0;
  let retryableFailures = 0;
  let idx = 0;
  const workers = Array.from({ length: CONCURRENCY }, () => (async () => {
    while (idx < toEnrich.length) {
      const feature = toEnrich[idx++];
      try {
        const enrichment = await enrichBuilding(feature, collegeName);
        if (enrichment) {
          // Only replace cached data after a definitive response. A transient
          // failure should not destroy the last known-good enrichment.
          for (const k of WIKI_FIELDS) delete feature.properties[k];
          delete feature.properties._wikiTried;
          Object.assign(feature.properties, enrichment);
          if (enrichment.wikiTitle) succeeded++;
        }
      } catch {
        // Network/API failures are not evidence that no article exists. Keep
        // cached data, but remove the marker so a normal future run retries.
        delete feature.properties._wikiTried;
        retryableFailures++;
      }
    }
  })());
  await Promise.all(workers);

  await writeJsonAtomic(file, data);
  console.log(`  ✓ ${slug}: ${succeeded}/${toEnrich.length} buildings matched a Wikipedia article`);
  if (retryableFailures) {
    console.warn(`  ! ${slug}: ${retryableFailures} transient failure(s) left unmarked for retry`);
  }
}

async function main() {
  const args = process.argv.slice(2);
  const availableSlugs = readdirSync(BATCH_DIR)
    .filter((f) => f.endsWith('.geojson'))
    .map((f) => f.replace(/\.geojson$/, ''));
  const { force, targets } = parseEnrichOptions(args, availableSlugs);

  console.log(`Enriching ${targets.length} campus(es) (force=${force})...`);
  for (const slug of targets) {
    await enrichCampus(slug, force);
  }
  console.log('Done.');
}

main().catch((err) => { console.error(err); process.exit(1); });

// Batch-fetches OSM building data for every college in the list,
// applies the campus filter (same rules as the client), and saves
// one geojson file per college to data/buildings/{slug}.geojson.
//
// Run:
//   node scripts/fetch-all-campuses.mjs
//
// Re-run whenever you want fresh data or add/remove colleges.

import { mkdirSync, existsSync } from 'node:fs';
import { writeJsonAtomic } from './atomic-json-write.mjs';
import { parseFetchOptions } from './fetch-options.mjs';
import { fetchWithTimeout } from './fetch-timeout.js';
import { geometryToLinearRing } from './geojson-ring.mjs';
import { validateOverpassResponse } from './overpass-response.mjs';

const OVERPASS_ENDPOINTS = [
  'https://overpass.kumi.systems/api/interpreter',
  'https://overpass-api.de/api/interpreter',
  'https://overpass.nchc.org.tw/api/interpreter',
];
const BUFFER_KM = 1.5;            // half-side of the bbox in km
const CONCURRENCY = 3;            // parallel college fetches
const MAX_RETRY = 3;
const REQUEST_TIMEOUT_MS = 120_000;

// Mirror of the client classifier — keep in sync with index.html.
function classify(t) {
  if (!t) return 'other';
  const b = t.building, a = t.amenity, l = t.leisure;
  if (b === 'university' || b === 'school' || b === 'college' || a === 'research_institute' || b === 'kindergarten') return 'academic';
  if (b === 'dormitory' || b === 'residential' || b === 'apartments' || b === 'house' || b === 'detached' || b === 'semidetached_house' || b === 'terrace') return 'residential';
  if (a === 'library' || b === 'library') return 'library';
  if (a === 'cafe' || a === 'restaurant' || a === 'food_court' || a === 'fast_food' || b === 'cafeteria') return 'dining';
  if (l === 'sports_centre' || l === 'stadium' || b === 'stadium' || b === 'sports_hall' || b === 'grandstand') return 'athletic';
  if (a === 'place_of_worship' || b === 'chapel' || b === 'church' || b === 'cathedral') return 'religious';
  if (a === 'hospital' || a === 'clinic' || b === 'hospital') return 'medical';
  return 'other';
}

function landuseToCategory(landuse) {
  switch (landuse) {
    case 'university': case 'school': case 'college': return 'academic';
    case 'hospital': return 'medical';
    case 'religious': return 'religious';
    case 'recreation_ground': return 'athletic';
    default: return null;
  }
}

function pointInPolygon(pt, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const xi = poly[i][0], yi = poly[i][1];
    const xj = poly[j][0], yj = poly[j][1];
    const intersect = ((yi > pt[1]) !== (yj > pt[1])) &&
      (pt[0] < ((xj - xi) * (pt[1] - yi)) / (yj - yi + 1e-12) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

const STRONG_BUILDING = new Set(['university','school','college','dormitory','library','hospital','stadium','cathedral','chapel','church','grandstand','kindergarten']);
const STRONG_AMENITY  = new Set(['university','library','research_institute','place_of_worship','hospital','clinic']);
const STRONG_LEISURE  = new Set(['sports_centre','stadium']);
const CAMPUS_OPERATOR = /university|college|school|institute|academy/i;

function bboxFor(lat, lng, km) {
  const latDelta = km / 111;
  const lngDelta = km / (111 * Math.cos((lat * Math.PI) / 180));
  return {
    south: lat - latDelta,
    north: lat + latDelta,
    west: lng - lngDelta,
    east: lng + lngDelta,
  };
}

async function queryOverpass(body) {
  let lastErr;
  for (const url of OVERPASS_ENDPOINTS) {
    for (let attempt = 0; attempt < MAX_RETRY; attempt++) {
      try {
        const res = await fetchWithTimeout(url, {
          method: 'POST',
          body: 'data=' + encodeURIComponent(body),
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
            'Accept': 'application/json',
            'User-Agent': 'usa-college-map/1.0 (https://github.com/Counselor-Sophie/usa-college-map)',
          },
        }, fetch, REQUEST_TIMEOUT_MS);
        if (res.status === 429 || res.status === 504 || res.status === 502) {
          lastErr = new Error(`${res.status} @ ${url}`);
          await new Promise((r) => setTimeout(r, 2000 * (attempt + 1)));
          continue;
        }
        if (!res.ok) {
          lastErr = new Error(`HTTP ${res.status} @ ${url}`);
          break;
        }
        return validateOverpassResponse(await res.json(), url);
      } catch (err) {
        lastErr = err;
        await new Promise((r) => setTimeout(r, 1000));
      }
    }
  }
  throw lastErr || new Error('All Overpass endpoints failed');
}

async function fetchCollege(college) {
  const { lat, lng, slug, name } = college;
  const out = `data/buildings/${slug}.geojson`;

  const b = bboxFor(lat, lng, BUFFER_KM);
  const query = `[out:json][timeout:90];
(
  way["building"](${b.south},${b.west},${b.north},${b.east});
  way["landuse"~"^(university|college|school|hospital|religious|recreation_ground)$"](${b.south},${b.west},${b.north},${b.east});
  way["amenity"="university"](${b.south},${b.west},${b.north},${b.east});
);
out geom tags;`;

  const t0 = Date.now();
  const data = await queryOverpass(query);
  const dt = Date.now() - t0;

  // Partition into buildings + context zones
  const buildings = [];
  const zones = [];
  let invalidGeometry = 0;
  for (const el of data.elements || []) {
    if (el.type !== 'way') continue;
    const ring = geometryToLinearRing(el.geometry);
    if (!ring) {
      invalidGeometry++;
      continue;
    }
    const tags = el.tags || {};
    if (tags.building) {
      buildings.push({ el, tags, ring });
    } else if (tags.landuse || tags.amenity === 'university') {
      const cat = tags.amenity === 'university' ? 'academic' : landuseToCategory(tags.landuse);
      if (cat) zones.push({ category: cat, ring });
    }
  }

  // Apply campus filter (same rules as client)
  const features = [];
  for (const b_ of buildings) {
    const t = b_.tags;
    const cat = classify(t);

    const strong =
      STRONG_BUILDING.has(t.building) ||
      STRONG_AMENITY.has(t.amenity) ||
      STRONG_LEISURE.has(t.leisure) ||
      (typeof t.operator === 'string' && CAMPUS_OPERATOR.test(t.operator));

    let finalCat = cat;
    if (!strong) {
      const cx = b_.ring.reduce((s, c) => s + c[0], 0) / b_.ring.length;
      const cy = b_.ring.reduce((s, c) => s + c[1], 0) / b_.ring.length;
      let zone = null;
      for (const z of zones) {
        if (pointInPolygon([cx, cy], z.ring)) { zone = z; break; }
      }
      if (!zone) continue; // drop: not campus-affiliated
      if (finalCat === 'other') finalCat = zone.category;
    }

    features.push({
      type: 'Feature',
      id: b_.el.id,
      properties: { osmId: b_.el.id, category: finalCat, ...t },
      geometry: { type: 'Polygon', coordinates: [b_.ring] },
    });
  }

  const fc = { type: 'FeatureCollection', features };
  mkdirSync('data/buildings', { recursive: true });
  await writeJsonAtomic(out, fc);

  const named = features.filter((f) => f.properties.name).length;
  console.log(`  ✓ ${name}: ${features.length} buildings (${named} named) in ${dt}ms`);
  if (invalidGeometry) {
    console.warn(`  ! ${name}: skipped ${invalidGeometry} way(s) with invalid polygon geometry`);
  }
}

